mapper.select:
SELECT A.SEQNO seqNo, FP1.FINPROD_MARKET_ID prodId, A.PROD_NAME prodName, FP2.FINPROD_MARKET_ID assetId, A.ASSET_NAME assetName, A.ASSET_TYPE assetType, A.PORTFOLIO_ID portfolioId, A.BUSS_NO bussNo, 'T01' ps, A.TRADE_DATE tradeDate, A.DEC_DATE decDate, A.PRIN_OVERDUE_DAY prinOverdueDay, A.INT_OVERDUE_DAY intOverdueDay, A.PURCHASE_TIME_GRADE purchaseTimeGrade, A.CURRENT_TIME_GRADE currentTimeGrade, A.PRE_PROSPECTIVE_PD preProspectivePd, A.PROSPECTIVE_PD prospectivePd, A.STAGE stage, A.LGD lgd, A.EAD ead, A.PRE_PROSPECTIVE_ECL preProspectiveEcl, A.PROSPECTIVE_ECL prospectiveEcl, A.ALLOW_MODEL_COVER allowModelCover, A.DATA_SOURCE dataSource FROM ASSET_LOSS_RESULT A LEFT JOIN FIN_PRODUCT FP1 ON A.PROD_ID = FP1.FINPROD_ID LEFT JOIN FIN_PRODUCT FP2 ON A.ASSET_ID = FP2.FINPROD_ID WHERE 1=1
AND A.PROD_ID in
#{item}
AND A.ASSET_ID in
#{item}
AND A.BUSS_NO in
#{item}
AND A.STAGE in
#{item}
AND A.DATA_SOURCE in
#{item}
AND A.TRADE_DATE >= #{tradeDateBegin}
AND A.TRADE_DATE <= #{tradeDateEnd}
AND A.DEC_DATE >= #{impairDateBegin}
AND A.DEC_DATE <= #{impairDateEnd}
ORDER BY DEC_DATE

SELECT COUNT(1)
FROM ASSET_LOSS_RESULT A
WHERE PROD_ID = #{prodId}
AND BUSS_NO = #{bussNo}
AND DEC_DATE = #{decDate}

select distinct NVL(d.TOTLE_TRADE_ID, d.TRADE_ID) as id, NVL(d.TOTLE_TRADE_ID, d.TRADE_ID) as text, d.PS || '/' || to_char(d.TRADE_DATE, 'yyyy-MM-dd') || '/' || e.PORTFOLIO_ID as object from FIN_PRODUCT a inner join FIN_PRODUCT_TYPE b on a.FINPROD_ID = b.FINPROD_ID and (b.TYPE_8 in ('F01', 'F05') or (b.TYPE_8 = 'F06' and b.TYPE_9 in ('08','09'))) inner join PTL_SEC_POSITION c on a.FINPROD_ID = c.FINPROD_ID and c.AMOUNT != 0
and c.CDATE = #{currentDate}
and c.INV_AIM IN ('AC','999999') and c.HODING_TYPE = '03' inner join TRD_PRODUCT_DEAL d on a.FINPROD_ID = d.FINPROD_ID and d.PS = 'T01' AND d.TRADE_STATUS != '03' AND d.is_cancel = 'N' inner join PTL_TRADE e on d.TRADE_ID = e.BUSI_NO inner join (select PORTFOLIO_ID,PARENT_PORTFOLIO_ID from PTL_PORTFOLIO where INVEST_YESORNO = 'Y') f on e.PORTFOLIO_ID = f.PORTFOLIO_ID and c.PORTFOLIO_ID = f.PORTFOLIO_ID inner join FIN_PRODUCT g on (f.PARENT_PORTFOLIO_ID = g.FINPROD_MARKET_ID or f.PORTFOLIO_ID = g.FINPROD_MARKET_ID) and g.FINPROD_TYPE2 = 'F16' where a.VDATE <= #{currentDate}
AND g.FINPROD_ID = #{prodId}
AND a.FINPROD_ID = #{assetId}
and (d.TOTLE_TRADE_ID like concat(concat('%',#{search}),'%') or d.TRADE_ID like concat(concat('%',#{search}),'%'))
and (d.TOTLE_TRADE_ID like concat(concat('%',#{initValue}),'%') or d.TRADE_ID like concat(concat('%',#{initValue}),'%'))

SELECT FINPROD_ID finprodId, FINPROD_ABBR finprodName FROM FIN_PRODUCT A
AND A.FINPROD_TYPE2 IN
#{item}
and (instr(A.FINPROD_ID, #{search}) > 0 or instr(A.FINPROD_NAME, #{search}) > 0 or instr(A.FINPROD_ABBR, #{search}) > 0)
and A.FINPROD_ID = #{initValue}
AND A.FINPROD_ID IN
#{item}

with tmp as ( select A.FINPROD_ID, A.CDATE, A.INV_AIM, SUM(A.AMOUNT) AMOUNT from PTL_SEC_POSITION A INNER JOIN PTL_PORTFOLIO C ON A.PORTFOLIO_ID = C.PORTFOLIO_ID AND C.INVEST_YESORNO = 'Y' INNER JOIN FIN_PRODUCT B ON A.FINPROD_ID = B.FINPROD_ID AND B.FINPROD_TYPE2 IN ('F01', 'F18') --债券、项目类 where A.HODING_TYPE = '03' --实际持仓 GROUP BY A.FINPROD_ID, A.CDATE, A.INV_AIM ) SELECT A.FINPROD_ID finprodId, A.FINPROD_ABBR finprodName FROM fin_product a inner join fin_product_type b on a.FINPROD_ID = b.FINPROD_ID where ( (b.type_8 = 'F01' or (b.type_8 = 'F06' and b.type_9 in ('08', '09'))) and exists( select 1 from tmp c where c.FINPROD_ID = a.FINPROD_ID and c.INV_AIM = 'AC' and c.CDATE = to_date(#{execDate,jdbcType=VARCHAR}, 'yyyy-MM-dd') and c.AMOUNT != 0 ) )
and (instr(A.FINPROD_ID, #{search}) > 0 or instr(A.FINPROD_NAME, #{search}) > 0 or instr(A.FINPROD_ABBR, #{search}) > 0)
and A.FINPROD_ID = #{initValue}
AND A.FINPROD_ID IN
#{item}

select A.TRADE_ID as id, A.TRADE_ID as text, A.PS || '/' || A.TRADE_DATE as object from TRD_PRODUCT_DEAL A inner join BOK_DEAL_ACCOUNTING E on E.BUSI_NO = A.TRADE_ID inner join FIN_PRODUCT B on B.FINPROD_ID = A.FINPROD_ID inner join FIN_PRODUCT_TYPE C on C.FINPROD_ID = B.FINPROD_ID
1=1 and A.IS_CANCEL ='N' and A.TRADE_STATUS !='03' and A.INV_AIM='AC'
and A.FINPROD_ID =#{finprodId}
and and to_char(A.TRADE_DATE,'yyyy-MM-dd')=#{tradeDateStr}
